const competitorState={data:null,loading:false,error:'',tab:'products',source:'all',search:'',archived:false,formOpen:false,draft:null,saving:false,formError:'',queueing:false,historySequence:0,matrixPack:'50',matrixStatus:'all',matrixSort:'name',selected:{},cuts:{},cut:'2',preview:false};
const competitorKinds={product:'Карточка товара',terms:'Доставка и скидки',catalog:'Страница ассортимента'};
