const competitorWarningLabels={weight_unknown:'Вес упаковки не определён',availability_unknown:'Наличие не подтверждено',weight_set_manually:'Вес упаковки задан вручную',variant_prices_unavailable:'Цена для каждой фасовки не определена',aggregate_from_price_ignored:'Цена «от» не используется вместо цены фасовки',multiple_products_unresolved:'На странице найдено несколько товаров; требуется проверка',watched_page_only_not_full_catalog:'Наблюдаем только выбранную страницу ассортимента'};
Object.assign(competitorErrors,{commercial_terms_unrecognized:'Условия скидок или доставки не распознаны',too_many_variants:'На странице слишком много вариантов; требуется отдельная ссылка на товар'});
function competitorWarnings(warnings){return [...new Set((warnings||[]).map(code=>competitorWarningLabels[code]||'Часть данных требует проверки по источнику'))].join(' · ');}
function competitorDate(value){if(!value)return 'ещё не было';const date=new Date(value);return Number.isNaN(date.getTime())?'дата не определена':date.toLocaleString('ru-RU',{timeZone:'Europe/Kiev',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});}
function competitorMoney(value,currency=''){const n=Number(value);return value===null||value===undefined||value===''||!Number.isFinite(n)?'Цена неизвестна':num(n,2)+(currency?' '+esc(currency):'');}
function competitorLink(url,label,classes=''){let safe='';try{const parsed=new URL(url);if(parsed.protocol==='https:'&&!parsed.username&&!parsed.password)safe=parsed.href;}catch(_){}return safe?`<a class="${classes}" href="${esc(safe)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`:`<span>${esc(label)}</span>`;}
function competitorSource(id){return (competitorState.data?.sources||[]).find(s=>s.id===id)||{id,name:id,role:id==='lavka'?'own':'competitor'};}
function competitorGroupName(group){const own=(competitorState.data?.targets||[]).find(t=>t.source_id==='lavka'&&t.match_group===group);return own?.label||group;}
function competitorOwn(target){return target.source_id==='lavka'||competitorSource(target.source_id).role==='own';}
function competitorTargets(kind){return (competitorState.data?.targets||[]).filter(t=>(!kind||t.kind===kind)&&(competitorState.archived||t.enabled)&&(competitorState.source==='all'||t.source_id===competitorState.source));}
function competitorStale(target){const success=Date.parse(target.last_success||'');const now=Date.parse(competitorState.data?.server_now||'')||Date.now();return !Number.isFinite(success)||now-success>48*3600000;}
function competitorStatus(target){const attempt=target.last_attempt;if(!target.enabled)return '<span class="competitor-status neutral">В архиве</span>';if(attempt?.state==='error')return '<span class="competitor-status error">Ошибка проверки</span>';if(!target.last_success)return '<span class="competitor-status pending">Ожидает первой проверки</span>';if(competitorStale(target))return '<span class="competitor-status pending">Данные устарели</span>';return '<span class="competitor-status ok">Проверено</span>';}
