function competitorMatrixRows(){
  const targets=(competitorState.data?.targets||[]).filter(target=>target.enabled&&target.kind==='product'),rows=[],ownTargets=targets.filter(competitorOwn);const groupCounts=new Map();ownTargets.forEach(target=>{if(target.match_group)groupCounts.set(target.match_group,(groupCounts.get(target.match_group)||0)+1);});
  for(const own of ownTargets){
    const group=own.match_group||'target-'+own.id,rowGroup=(groupCounts.get(group)||0)>1?group+'@'+own.id:group;
    const grouped=targets.filter(target=>target.id===own.id||!competitorOwn(target)&&Boolean(own.match_group)&&target.match_group===own.match_group),entry=competitorMatrixEntries(own),weights=new Set(competitorRequestedWeights(own.pack_label));
    entry.offers.forEach(offer=>{const grams=offer.unit==='pack'?competitorWeight(entry.target,offer):null;if(grams!==null)weights.add(grams);});
    if(Number(own.grams_override)>0)weights.add(Number(own.grams_override));
    if(!weights.size)competitorRequestedWeights(own.label).forEach(grams=>weights.add(grams));
    if(!weights.size)continue;
    weights.add(50);
    for(const grams of [...weights].sort((a,b)=>a-b)){
      const row={key:rowGroup+'|'+grams,group,rowGroup,grams,label:entry.target.label||own.label||'Товар',own,targets:grouped,cells:{}};
      competitorMatrixSources.forEach(source=>row.cells[source]=competitorMatrixCell(row,source));
      const valid=competitorMatrixSources.map(source=>row.cells[source]).filter(cell=>cell.eligible),competitors=competitorMatrixSources.filter(source=>source!=='lavka').map(source=>row.cells[source]).filter(cell=>cell.eligible);
      row.minimum=valid.length>=2?Math.min(...valid.map(cell=>cell.price)):null;row.competitorMinimum=competitors.length?Math.min(...competitors.map(cell=>cell.price)):null;row.comparable=row.cells.lavka.eligible&&row.competitorMinimum!==null;
      row.above=row.comparable&&row.cells.lavka.price>row.competitorMinimum+.004;row.knownPack=grouped.some(target=>competitorMatrixEntries(target).offers.some(offer=>offer.unit==='pack'&&competitorWeight(target,offer)===grams));
      rows.push(row);
    }
  }
  return rows;
}
function competitorVisibleRows(){let rows=competitorMatrixRows(),search=competitorState.search.trim().toLocaleLowerCase();if(competitorState.matrixPack==='50')rows=rows.filter(row=>row.grams===50);else if(competitorState.matrixPack==='minimum'){const minimum=new Map();rows.forEach(row=>{if(row.cells.lavka.eligible&&(!minimum.has(row.rowGroup)||row.grams<minimum.get(row.rowGroup)))minimum.set(row.rowGroup,row.grams);});rows=rows.filter(row=>row.grams===(minimum.get(row.rowGroup)||50));}if(search)rows=rows.filter(row=>[row.label,row.group].join(' ').toLocaleLowerCase().includes(search));if(competitorState.matrixStatus==='ready')rows=rows.filter(row=>row.comparable);if(competitorState.matrixStatus==='above')rows=rows.filter(row=>row.above);if(competitorState.matrixStatus==='gaps')rows=rows.filter(row=>!row.comparable);rows.sort(competitorState.matrixSort==='gap'?(a,b)=>Number(b.above)-Number(a.above)||a.label.localeCompare(b.label,'uk'):(a,b)=>a.label.localeCompare(b.label,'uk')||a.grams-b.grams);return rows;}
function competitorShortDate(value){const date=new Date(value||'');return Number.isNaN(date.getTime())?'Дата неизвестна':date.toLocaleString('ru-RU',{timeZone:'Europe/Kiev',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});}
function competitorMatrixDetailButton(row,source,label,classes=''){return `<button class="competitor-cell-detail ${classes}" type="button" data-comp-action="matrix-detail" data-row="${esc(row.key)}" data-source="${source}" aria-label="${esc(label+' · '+competitorSource(source).name+' · '+row.label+' · '+num(row.grams,2)+' г')}">${esc(label)}</button>`;}
function competitorMatrixPrice(row,source){const cell=row.cells[source],best=cell.eligible&&row.minimum!==null&&Math.abs(cell.price-row.minimum)<.005;let content;if(cell.eligible){content=`${competitorLink(cell.target.url,competitorMoney(cell.price),'competitor-cell-price')}<span class="competitor-cell-currency">UAH${best?' · минимум среди проверенных':''}</span>${competitorMatrixDetailButton(row,source,source==='lavka'?cell.provenance+' · '+competitorShortDate(cell.target.last_success):competitorShortDate(cell.target.last_success),best?'best-detail':'')}`;}else{content=cell.offer&&cell.price!==null?`${competitorLink(cell.target.url,competitorMoney(cell.price),'competitor-cell-price saved')}<span class="competitor-cell-currency">UAH · прежняя цена</span>`:'<span class="competitor-cell-dash" aria-hidden="true">—</span>';content+=competitorMatrixDetailButton(row,source,cell.reason,'status-'+cell.state);}return `<td class="competitor-matrix-price ${source==='lavka'?'own':''} ${best?'is-best':''} ${cell.eligible?'eligible':'not-comparable'}" data-source="${source}"${cell.eligible?' data-price="'+esc(cell.price.toFixed(2))+'"':''}>${content}</td>`;}
function competitorCut(row){const value=competitorState.cuts[row.key]??competitorState.cut;return value===''?null:Number(value);}
function competitorSuggestion(row){const percent=competitorCut(row);if(!row.comparable||percent===null||!Number.isFinite(percent)||percent<0||percent>50)return null;const own=row.cells.lavka.price;const competitorCents=Math.round(row.competitorMinimum*100),basisPoints=Math.round(percent*100),proposed=Math.floor(competitorCents*(10000-basisPoints)/10000)/100;if(proposed<=0)return null;return {price:Math.min(own,proposed),keep:own<=proposed,percent};}
function competitorDraftCell(row){const selected=Boolean(competitorState.selected[row.key]),suggestion=competitorSuggestion(row),shown=competitorState.preview&&selected&&suggestion;return `<td class="competitor-draft-cell"><label class="competitor-row-select"><input type="checkbox" data-matrix-select="${esc(row.key)}" ${selected?'checked':''} ${row.comparable?'':'disabled'} aria-label="Выбрать ${esc(row.label)} ${num(row.grams,2)} г для черновика"><span>${row.comparable?'В черновик':'Нужны цены'}</span></label><label class="competitor-row-cut"><span>Ниже конкурента, %</span><input type="number" min="0" max="50" step="0.1" inputmode="decimal" data-matrix-cut="${esc(row.key)}" value="${esc(competitorState.cuts[row.key]??competitorState.cut)}" ${row.comparable?'':'disabled'} aria-label="Снижение в процентах для ${esc(row.label)} ${num(row.grams,2)} г"></label>${shown?`<div class="competitor-suggestion" data-price="${esc(suggestion.price.toFixed(2))}"><strong>${competitorMoney(suggestion.price)} UAH</strong><span>${suggestion.keep?'Оставить нашу цену':'Предложение · −'+num(suggestion.percent,1)+'% от конкурента'}</span></div>`:'<span class="competitor-draft-placeholder">'+(selected?'Нажмите «Рассчитать черновик»':'—')+'</span>'}</td>`;}
function competitorProducts(){const rows=competitorVisibleRows(),selected=rows.filter(row=>competitorState.selected[row.key]&&row.comparable),ready=rows.filter(row=>row.comparable),catalog=competitorState.data?.own_catalog;return `<div class="competitor-section-heading competitor-report-heading"><div><h2>Сравнение цен</h2></div><button class="button" data-comp-action="tab" data-tab="links">Настроить ссылки →</button></div><div class="competitor-matrix-filters"><label class="competitor-search-label"><span class="sr-only">Найти товар</span><input id="competitor-search" type="search" placeholder="Найти специю…" value="${esc(competitorState.search)}"></label><label><span>Фасовки</span><select id="competitor-matrix-pack"><option value="50" ${competitorState.matrixPack==='50'?'selected':''}>50 г · стартовый список</option><option value="minimum" ${competitorState.matrixPack==='minimum'?'selected':''}>Минимальные подтверждённые</option><option value="all" ${competitorState.matrixPack==='all'?'selected':''}>Все выбранные фасовки</option></select></label><label><span>Показать</span><select id="competitor-matrix-status"><option value="all">Все товары</option><option value="ready" ${competitorState.matrixStatus==='ready'?'selected':''}>Можно сравнить</option><option value="above" ${competitorState.matrixStatus==='above'?'selected':''}>Наша цена выше</option><option value="gaps" ${competitorState.matrixStatus==='gaps'?'selected':''}>Нужны данные</option></select></label></div><div class="competitor-report-note"><span><b>${rows.length}</b> строк · <b>${ready.length}</b> можно сравнить</span><span>Сравниваем точную фасовку в UAH. Прочерк раскрывает причину.</span></div>${catalog?.state&&catalog.state!=='ok'?'<p class="competitor-data-note">База магазина: '+(catalog.last_success?'сохранены на '+esc(competitorDate(catalog.last_success))+', последняя синхронизация не завершена.':'ещё не подключена.')+' Источник — под ценой.</p>':''}<p class="competitor-matrix-scroll-hint">Таблицу можно прокручивать вправо → <span>Нажмите статус под ценой для деталей и источника.</span></p>${rows.length?`<div class="competitor-matrix-scroll" role="region" aria-label="Сравнение цен по магазинам. Таблица прокручивается горизонтально" tabindex="0"><table class="competitor-matrix"><caption class="sr-only">Цены за указанную фасовку в UAH. Прочерк не означает отсутствие товара у магазина.</caption><thead><tr><th scope="col" class="competitor-matrix-name">Товар</th><th scope="col" class="competitor-matrix-pack">Фасовка</th>${competitorMatrixSources.map(source=>`<th scope="col" class="${source==='lavka'?'own':''}">${source==='lavka'?'Лавка специй':esc(competitorSource(source).name)}${source==='lavka'?'<small>Наша цена</small>':''}</th>`).join('')}<th scope="col" class="competitor-draft-heading">Предложенная цена<small>Только черновик</small></th></tr></thead><tbody>${rows.map(row=>`<tr data-matrix-row="${esc(row.key)}"><th scope="row" class="competitor-matrix-name"><button type="button" class="competitor-row-name" data-comp-action="matrix-detail" data-row="${esc(row.key)}" data-source="lavka">${esc(row.label)}</button>${row.comparable?`<span class="competitor-row-position ${row.above?'above':'leading'}">${row.above?'Наша выше на '+num((row.cells.lavka.price/row.competitorMinimum-1)*100,1)+'%':'Наша цена — минимум'}</span>`:'<span class="competitor-row-position">Сравнение ещё не готово</span>'}</th><td class="competitor-matrix-pack"><strong>${num(row.grams,2)} г</strong>${!row.knownPack?'<small>Нужно проверить фасовку</small>':''}</td>${competitorMatrixSources.map(source=>competitorMatrixPrice(row,source)).join('')}${competitorDraftCell(row)}</tr>`).join('')}</tbody></table></div>`:'<div class="competitor-empty compact"><h3>Под этот фильтр строк нет</h3><p>Выберите другую фасовку или уберите фильтр. Поштучные товары доступны во вкладке «Ссылки и сопоставления».</p></div>'}<div class="competitor-draft-toolbar"><div><strong>Черновик цен</strong><span>Выберите строки и рассчитайте предложение. Текущие цены магазина сохраняются.</span></div><label>Ниже конкурента на <input id="competitor-batch-cut" type="number" min="0" max="50" step="0.1" inputmode="decimal" value="${esc(competitorState.cut)}" aria-label="Общее снижение от цены лучшего конкурента в процентах"> %</label><button type="button" class="button" data-comp-action="matrix-select-ready">Выбрать доступные (${ready.length})</button><button type="button" class="button primary" data-comp-action="matrix-preview" ${selected.length?'':'disabled'}>Рассчитать черновик (${selected.length})</button>${Object.values(competitorState.selected).some(Boolean)?'<button class="competitor-text-button" type="button" data-comp-action="matrix-clear">Снять выбор</button>':''}</div><p class="competitor-scope-note">50 г — выбранная фасовка. Прочерк означает, что цена этой упаковки не подтверждена. Цену другой фасовки не пересчитываем. Оптовые, условные, неподтверждённые и устаревшие цены не определяют минимум. Доставка не включена. Черновик не повышает нашу цену и ничего не записывает в магазин.</p>`;}
function competitorMatrixDetail(key,source){const row=competitorMatrixRows().find(item=>item.key===key);if(!row)return;state.customer=null;openDrawer('СРАВНЕНИЕ · '+num(row.grams,2)+' Г');const cell=row.cells[source],targets=row.targets.filter(target=>target.source_id===source);$('#drawer-content').innerHTML=`<div class="competitor-history competitor-price-detail"><span class="competitor-source-label">${esc(competitorSource(source).name)}</span><h2 class="drawer-name">${esc(row.label)}</h2><p class="competitor-detail-pack">Сравниваем ${num(row.grams,2)} г</p><p class="competitor-explanation">${cell.eligible?'Точная фасовка, обычная цена, наличие подтверждено.':esc(cell.reason)+'. Эта ячейка не участвует в определении минимальной цены.'}</p>${targets.length?targets.map(target=>{const entry=competitorMatrixEntries(target);return `<section class="competitor-detail-target"><h3>${esc(entry.target.label||target.label)}</h3><p>${competitorLink(entry.target.url,'Открыть карточку товара')}</p><p class="competitor-muted">Источник цены: ${esc(entry.provenance)} · Последний успех: ${esc(competitorDate(entry.target.last_success))}</p>${entry.offers.length?entry.offers.map(offer=>competitorOffer(entry.target,offer,false)).join(''):'<p class="competitor-muted">Сохранённой цены пока нет.</p>'}${competitorError(entry.target)}${!competitorOwn(target)&&!target.match_confirmed?`<p class="competitor-warning">Проверьте состав, качество и товар по ссылке. Фасовки сравниваются отдельно.</p><button class="button primary" type="button" data-comp-action="matrix-confirm" data-id="${target.id}" ${competitorState.saving?'disabled':''}>Подтвердить сопоставление</button>`:''}${entry.catalog?'<p class="competitor-muted">Наши цены поступают из ежедневной синхронизации базы магазина.</p>':''}${competitorTargetActions(target,entry.catalog)}</section>`;}).join(''):`<p class="competitor-muted">Ссылка этого магазина ещё не добавлена к товару.</p><button class="button primary" type="button" data-comp-action="matrix-add" data-row="${esc(row.key)}" data-source="${source}">Добавить ссылку</button>`}</div>`;}
async function competitorMatrixConfirm(id){const target=competitorState.data?.targets.find(item=>item.id===id);if(!target||competitorState.saving)return;competitorState.saving=true;try{await api('/api/competitors/targets/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(competitorBody({...target,match_confirmed:true}))});await competitorsLoad();toast('Сопоставление подтверждено. Сравниваются только одинаковые фасовки.');document.getElementById('drawer')?.close();}catch(error){toast(error.message);}finally{competitorState.saving=false;competitorsRender();}}

function competitorWatcher(target){return `<article class="competitor-watcher ${!target.enabled?'archived':''}"><div class="competitor-card-top"><span class="competitor-source-label">${esc(competitorSource(target.source_id).name)} · ${esc(competitorKinds[target.kind]||target.kind)}</span>${competitorStatus(target)}</div><h3>${competitorLink(target.url,target.label||competitorKinds[target.kind]||'Страница')}</h3>${target.observation?.text?'<details class="competitor-terms-text"><summary>Прочитать сохранённые условия</summary><p>Текст страницы на момент проверки. Детали скидки и доставки проверяйте по ссылке источника.</p><pre>'+esc(target.observation.text)+'</pre></details>':target.kind==='terms'?'<p class="competitor-muted">Условия появятся после успешной проверки. Изменения страницы сохраняются в истории.</p>':''}${target.kind==='catalog'&&target.observation?'<p class="competitor-muted">Ссылок в последнем снимке: '+num((target.observation.links||[]).length)+'. Наблюдаем только эту страницу.</p>':''}${competitorError(target)}<div class="competitor-freshness">Последний успех: ${esc(competitorDate(target.last_success))}</div>${competitorTargetActions(target)}</article>`;}
function competitorTerms(){const targets=competitorTargets('terms');return `<div class="competitor-section-heading"><div><h2>Доставка, акции и скидки</h2><p>Сохранённые условия со страниц магазинов.</p></div><button class="button primary" data-comp-action="add" data-kind="terms">+ Добавить страницу</button></div>${competitorFilter()}<div class="competitor-explanation">Условия могут зависеть от суммы заказа, категории и количества. Указанные пользователем сведения — заметки для проверки; подтверждение даёт ссылка и дата успешного снимка.</div><div class="competitor-watcher-grid">${targets.map(competitorWatcher).join('')||'<p class="competitor-muted">Под выбранный фильтр страниц нет.</p>'}</div>`;}
function competitorDiscoveries(){const rows=(competitorState.data?.discoveries||[]).filter(d=>!d.baseline&&(competitorState.source==='all'||d.source_id===competitorState.source));return `<div class="competitor-section-heading"><div><h2>Замечено в ассортименте</h2><p>Новые для наблюдаемой страницы ссылки на товары.</p></div><button class="button" data-comp-action="add" data-kind="catalog">+ Наблюдать страницу</button></div>${competitorFilter()}<div class="competitor-explanation">Первый снимок создаёт точку отсчёта. Следующие показывают ранее не замеченные ссылки. Это дата обнаружения на выбранной странице, а не дата появления товара в продаже; весь каталог автоматически не обходится.</div><div class="competitor-discovery-list">${rows.map(d=>`<article><div><span class="competitor-source-label">${esc(competitorSource(d.source_id).name)}</span><h3>${competitorLink(d.url,d.title||d.url)}</h3><p>Впервые замечено: ${esc(competitorDate(d.first_seen))}</p></div><button class="button" data-comp-action="track-discovery" data-url="${esc(d.url)}" data-source="${esc(d.source_id)}" data-title="${esc(d.title||'')}">Следить за ценой</button></article>`).join('')||'<div class="competitor-empty compact"><h3>Новых ссылок пока не замечено</h3><p>Результат появится после сравнения двух успешных снимков страницы ассортимента.</p></div>'}</div><h3 class="competitor-subheading">Наблюдаемые страницы</h3><div class="competitor-watcher-grid">${competitorTargets('catalog').map(competitorWatcher).join('')||'<p class="competitor-muted">Добавьте страницу категории или новинок.</p>'}</div>`;}
function competitorChanges(){const rows=(competitorState.data?.changes||[]).filter(c=>competitorState.source==='all'||c.source_id===competitorState.source);return `<div class="competitor-section-heading"><div><h2>История изменений</h2><p>Цены, наличие и содержимое наблюдаемых страниц.</p></div></div>${competitorFilter()}<div class="competitor-changes">${rows.map(c=>{const t=(competitorState.data?.targets||[]).find(t=>t.id===c.target_id);return `<article><span class="competitor-change-dot" aria-hidden="true"></span><div><div class="competitor-card-top"><span class="competitor-source-label">${esc(competitorSource(c.source_id).name)}</span><time>${esc(competitorDate(c.occurred_at))}</time></div><h3>${esc(t?.label||t?.observation?.title||competitorKinds[c.kind]||'Наблюдаемая страница')}</h3><p>${esc(c.message||'Изменились сохранённые данные страницы')}</p><button class="competitor-text-button" data-comp-action="history" data-id="${c.target_id}">Открыть историю →</button></div></article>`;}).join('')||'<div class="competitor-empty compact"><h3>История пока пуста</h3><p>Первое успешное чтение станет начальной точкой. Последующие изменения появятся здесь.</p></div>'}</div>`;}
function competitorSourceNotes(source){const notes=source.notes;if(!notes)return '';const parts=typeof notes==='string'?[notes]:Array.isArray(notes)?notes.map(n=>typeof n==='string'?n:n.text||''):[notes.text||''];const text=parts.filter(Boolean).join(' ');return text?'<p class="competitor-source-note">'+esc(text)+'<small>Сведения пользователя · пока не подтверждены проверкой страницы.</small></p>':'';}
function competitorSources(){return `<div class="competitor-section-heading"><div><h2>Магазины и наблюдение</h2><p>Четыре конкурента и публичные страницы «Лавки специй».</p></div><button class="button primary" data-comp-action="add" data-kind="product">+ Добавить ссылку</button></div><div class="competitor-source-grid">${(competitorState.data?.sources||[]).map(s=>{const targets=(competitorState.data.targets||[]).filter(t=>t.source_id===s.id&&t.enabled),products=targets.filter(t=>t.kind==='product');return `<article class="competitor-source-card ${s.id==='lavka'?'own':''}"><span class="competitor-source-label">${s.id==='lavka'?'Наш магазин':'Конкурент'}</span><h3>${competitorLink(s.base_url,s.name)}</h3><p>${products.length} товаров · ${targets.length-products.length} страниц условий и ассортимента</p>${competitorSourceNotes(s)}<div class="competitor-source-actions"><button class="button" data-comp-action="add" data-source="${esc(s.id)}" data-kind="product">+ Товар</button><button class="competitor-text-button" data-comp-action="add" data-source="${esc(s.id)}" data-kind="terms">Условия</button><button class="competitor-text-button" data-comp-action="add" data-source="${esc(s.id)}" data-kind="catalog">Ассортимент</button></div></article>`;}).join('')}</div><section class="competitor-run-panel"><h3>Как обновляются данные</h3><p>Каждая активная ссылка проверяется примерно раз в сутки. Кнопка «В очередь» назначает следующую фоновую проверку. «Обновить результаты» читает сохранённые данные кабинета.</p>${(competitorState.data?.runs||[]).length?'<details><summary>Последние запуски фоновой проверки</summary>'+competitorState.data.runs.slice(0,5).map(r=>'<p>'+esc(competitorDate(r.finished_at||r.started_at||r.at))+' · '+num(r.checked??r.processed??r.attempted??0)+' проверок'+(r.errors?' · ошибок: '+num(r.errors):'')+'</p>').join('')+'</details>':'<p class="competitor-muted">Сведений о фоновых запусках пока нет. Расписание должно быть настроено на хостинге.</p>'}</section>`;}
function competitorFailedTargets(){return (competitorState.data?.targets||[]).filter(target=>target.enabled&&target.last_attempt?.state==='error'&&!competitorOwnCatalogAuthority(target)).sort((a,b)=>String(b.last_attempt.checked_at||'').localeCompare(String(a.last_attempt.checked_at||''))||a.id-b.id);}
function competitorShowErrors(){competitorCaptureDraft();competitorState.tab='errors';competitorState.source='all';competitorState.search='';competitorState.archived=false;competitorsRender();document.getElementById('competitor-errors-title')?.focus({preventScroll:true});document.getElementById('competitor-tabpanel')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function competitorCaptureDraft(){if(!competitorState.formOpen||competitorState.saving)return;const form=document.getElementById('competitor-target-form');if(!form)return;const fields=new FormData(form),previous=competitorState.draft||{};competitorState.draft={...previous,source_id:fields.get('source_id')||previous.source_id,kind:fields.get('kind')||previous.kind,url:fields.get('url')??previous.url,label:fields.get('label')||'',grams_override:fields.get('grams_override')===''?null:fields.get('grams_override'),pack_label:fields.get('pack_label')||'',match_group:fields.get('match_group')||'',match_confirmed:fields.has('match_confirmed'),enabled:previous.enabled!==false};}
function competitorForm(){if(!competitorState.formOpen)return '';const d=competitorState.draft||{},editing=Boolean(d.id),product=d.kind==='product';return `<section class="competitor-form-panel" aria-labelledby="competitor-form-title"><div class="competitor-section-heading"><div><span class="competitor-source-label">${editing?'Настройки наблюдения':'Новая ссылка'}</span><h2 id="competitor-form-title">${editing?'Настроить карточку':'Что будем наблюдать?'}</h2></div><button class="competitor-close" type="button" data-comp-action="cancel-form" aria-label="Закрыть форму">✕</button></div><form id="competitor-target-form" ${competitorState.saving?'aria-busy="true"':''}><fieldset ${competitorState.saving?'disabled':''}><div class="competitor-form-grid"><label>Магазин<select name="source_id" ${editing?'disabled':''}>${(competitorState.data?.sources||[]).map(s=>`<option value="${esc(s.id)}" ${d.source_id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Тип страницы<select name="kind" ${editing?'disabled':''}>${Object.entries(competitorKinds).map(([key,label])=>`<option value="${key}" ${d.kind===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="full">Ссылка на страницу<input name="url" type="url" placeholder="https://…" required maxlength="2000" value="${esc(d.url||'')}" ${editing?'readonly':''}><small>${editing?'Адрес, магазин и тип сохраняют историю. Для другого адреса добавьте новую ссылку.':'Точный адрес товара, условий доставки или одной страницы каталога выбранного магазина.'}</small></label><label class="full">Название в кабинете<input name="label" maxlength="200" placeholder="Например, Корица цейлонская, 100 г" value="${esc(d.label||'')}"></label>${product?`<label>Вес упаковки, г <span class="competitor-optional">если не определится на сайте</span><input name="grams_override" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" value="${esc(d.grams_override??'')}"><small>Применяется только к одной однозначной фасовке. При нескольких вариантах используем распознанный вес каждой цены.</small></label><label>Приоритетные фасовки / примечание<input name="pack_label" maxlength="100" placeholder="Банка 100 г" value="${esc(d.pack_label||'')}"></label><label class="full">Группа сравнения<input name="match_group" list="competitor-groups" maxlength="120" placeholder="Выберите товар нашей Лавки или задайте группу" value="${esc(d.match_group||'')}"><datalist id="competitor-groups">${[...new Set((competitorState.data?.targets||[]).filter(t=>t.source_id==='lavka'&&t.match_group).map(t=>t.match_group))].map(group=>'<option value="'+esc(group)+'">'+esc(competitorGroupName(group))+'</option>').join('')}</datalist><small>Выберите товар нашей Лавки из списка. Одну группу задайте сопоставимым карточкам конкурентов; новая группа может иметь понятное название.</small></label><label class="competitor-confirmation full"><input name="match_confirmed" type="checkbox" ${d.match_confirmed?'checked':''}><span>Я проверила состав, качество и фасовку: товар подходит для сравнения в этой группе.<small>Название само по себе не подтверждает одинаковое качество. Цены с условиями показываются отдельно.</small></span></label>`:'<p class="competitor-form-note full">'+(d.kind==='catalog'?'Сохраняем ссылки с этой страницы. Первый снимок — точка отсчёта; следующие помогают заметить изменения ассортимента.':'Сохраняем текст выбранной страницы. Детали доставки, порог заказа и условия скидок можно сравнить по датированным снимкам.')+'</p>'}</div>${competitorState.formError?'<p class="competitor-form-error" role="alert" tabindex="-1">'+esc(competitorState.formError)+'</p>':''}<div class="competitor-form-actions"><button class="button primary" type="submit">${competitorState.saving?'Сохраняем…':editing?'Сохранить настройки':'Добавить в наблюдение'}</button><button class="button" type="button" data-comp-action="cancel-form">Отмена</button>${editing?`<button class="competitor-text-button ${d.enabled?'danger-text':''}" type="button" data-comp-action="archive" data-id="${d.id}">${d.enabled?'Переместить в архив':'Возобновить наблюдение'}</button>`:''}</div></fieldset></form></section>`;}
function competitorsView(){
  const c=competitorState,data=c.data;if(!data)return `<div class="competitors-module"><div class="competitor-empty"><span aria-hidden="true">⚑</span><h2>${c.loading?'Открываем сравнение…':'Цены конкурентов'}</h2><p>${c.error?esc(c.error):'Загружаем сохранённые цены.'}</p>${c.error?'<button class="button primary" data-comp-action="refresh">Повторить загрузку</button>':''}</div></div>`;
  const rows=competitorMatrixRows().filter(row=>row.grams===50),ready=rows.filter(row=>row.comparable),above=rows.filter(row=>row.above),errors=competitorFailedTargets();
  const tabs=[['products','Сравнение цен'],['links','Ссылки и сопоставления'],['changes','Изменения'],['terms','Доставка и скидки'],['discoveries','Ассортимент'],['sources','Магазины'],['errors','Ошибки ('+num(errors.length)+')']];
  return `<div class="competitors-module"><section class="competitor-report-hero"><div><p>Ежедневное сравнение одинаковых фасовок.<br>Зелёным — минимум среди проверенных цен.</p></div><button class="button" type="button" data-comp-action="refresh" ${c.loading?'disabled':''}>${c.loading?'Обновляем…':'↻ Обновить данные'}</button></section><div class="competitor-report-summary"><span><strong>${num(rows.length)}</strong> товаров в списке 50 г</span><span><strong>${num(ready.length)}</strong> можно сравнить</span><button type="button" data-comp-action="matrix-show-above"><strong>${num(above.length)}</strong> наша цена выше</button><button type="button" data-comp-action="show-errors" class="competitor-checks-pill" aria-label="Показать ошибки проверок: ${num(errors.length)}">Проверки${errors.length?' · '+num(errors.length)+' с ошибкой':' · без ошибок'} <span aria-hidden="true">→</span></button></div>${c.error?'<div class="notice" role="alert">'+esc(c.error)+' Сохранённые результаты остаются на экране.</div>':''}<div class="competitor-nav"><div class="competitor-tabs" role="tablist" aria-label="Мониторинг конкурентов">${tabs.map(([id,label])=>`<button id="competitor-tab-${id}" type="button" role="tab" aria-selected="${c.tab===id}" aria-controls="competitor-tabpanel" tabindex="${c.tab===id?'0':'-1'}" class="${c.tab===id?'active':''}" data-comp-action="tab" data-tab="${id}">${label}</button>`).join('')}</div>${c.tab!=='products'?`<button class="competitor-text-button" data-comp-action="queue" ${c.queueing?'disabled':''}>${c.queueing?'Добавляем…':'Все ссылки в очередь →'}</button>`:''}</div>${competitorForm()}<section id="competitor-tabpanel" role="tabpanel" aria-labelledby="competitor-tab-${c.tab}">${({products:competitorProducts,links:competitorLinks,errors:competitorErrorsView,changes:competitorChanges,terms:competitorTerms,discoveries:competitorDiscoveries,sources:competitorSources}[c.tab]||competitorProducts)()}</section><p class="competitor-footer">Проверяем страницы раз в сутки. «Обновить данные» показывает сохранённый результат. Время — Киев. Прочерк не означает, что у магазина нет товара.</p></div>`;
}
function competitorErrorsView(){const targets=competitorFailedTargets();return `<div class="competitor-section-heading"><div><h2 id="competitor-errors-title" tabindex="-1">Проверки, требующие внимания</h2><p>Технический журнал: каждая строка — одна страница. Предыдущие успешные данные сохраняются.</p></div><div class="competitor-checks-actions"><button class="button" type="button" data-comp-action="copy-errors">Скопировать список ошибок</button><button class="button" type="button" data-comp-action="refresh">Обновить журнал</button></div></div><p class="competitor-scope-note">${num(targets.length)} страниц с ошибкой последней проверки. HTTP 200 означает, что страница загрузилась; данные на ней могут требовать другого способа чтения.</p><div class="competitor-errors-list competitor-checks-list">${targets.map(target=>`<article class="competitor-check-row competitor-error-card" data-target-id="${target.id}"><div><span class="competitor-source-label">${esc(competitorSource(target.source_id).name)} · ${esc(competitorKinds[target.kind]||'Страница')}</span><h3>${competitorLink(target.url,target.label||target.observation?.title||'Страница без названия')}</h3><p>${esc(competitorErrors[target.last_attempt.error_code]||'Проверка не завершена')}${target.last_attempt.http_status?' · HTTP '+esc(target.last_attempt.http_status):''}</p><small>Попытка: ${esc(competitorDate(target.last_attempt.checked_at))} · Успех: ${esc(competitorDate(target.last_success))}</small></div>${competitorTargetActions(target)}</article>`).join('')||'<div class="competitor-empty compact"><h3>Ошибок проверок нет</h3><p>У активных страниц нет ошибок последней попытки. Неполные и устаревшие цены отмечены в сравнении отдельно.</p></div>'}</div>`;}

function competitorsRender(){if(state.view!=='competitors')return;const scroll=document.querySelector('.competitor-matrix-scroll'),left=scroll?.scrollLeft||0;$('#content').innerHTML=competitorsView();const next=document.querySelector('.competitor-matrix-scroll');if(next)next.scrollLeft=left;}
async function competitorsLoad(){if(competitorState.loading)return;competitorCaptureDraft();competitorState.loading=true;competitorState.error='';competitorsRender();try{const result=await api('/api/competitors');if(!Array.isArray(result.targets)||!Array.isArray(result.sources))throw Error('Мониторинг вернул неполные данные.');competitorState.data={...result,changes:result.changes||[],discoveries:result.discoveries||[],runs:result.runs||[]};}catch(error){competitorState.error=error.message;}finally{competitorState.loading=false;competitorsRender();}}
function competitorOpenForm(draft){competitorCaptureDraft();document.getElementById('drawer')?.close();competitorState.draft={source_id:(competitorState.data?.sources||[])[0]?.id||'lavka',kind:'product',url:'',label:'',enabled:true,grams_override:null,pack_label:'',match_group:'',match_confirmed:false,...draft};competitorState.formOpen=true;competitorState.formError='';competitorsRender();requestAnimationFrame(()=>{document.querySelector('.competitor-form-panel')?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#competitor-target-form [name=url]')?.focus({preventScroll:true});});}
function competitorBody(t){return {source_id:t.source_id,kind:t.kind,url:t.url,label:t.label||'',enabled:Boolean(t.enabled),grams_override:t.grams_override===''||t.grams_override===null||t.grams_override===undefined?null:Number(t.grams_override),pack_label:t.pack_label||'',match_group:t.kind==='product'?t.match_group||'':'',match_confirmed:t.kind==='product'&&Boolean(t.match_confirmed)};}
async function competitorSave(){if(competitorState.saving)return;competitorCaptureDraft();const draft=competitorState.draft;if(draft.match_confirmed&&!String(draft.match_group||'').trim()){competitorState.formError='Для подтверждённого сравнения задайте общую группу товаров.';competitorsRender();document.querySelector('.competitor-form-error')?.focus();return;}competitorState.saving=true;competitorState.formError='';competitorsRender();try{await api('/api/competitors/targets'+(draft.id?'/'+draft.id:''),{method:draft.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(competitorBody(draft))});competitorState.formOpen=false;competitorState.draft=null;await competitorsLoad();toast('Ссылка сохранена. Данные появятся после фоновой проверки.');}catch(error){competitorState.formError=error.message;}finally{competitorState.saving=false;competitorsRender();document.querySelector('.competitor-form-error')?.focus();}}
async function competitorArchive(id){const target=competitorState.data.targets.find(t=>t.id===id);if(!target||competitorState.saving)return;competitorState.saving=true;competitorsRender();try{await api('/api/competitors/targets/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(competitorBody({...target,enabled:!target.enabled}))});competitorState.formOpen=false;competitorState.draft=null;await competitorsLoad();toast(target.enabled?'Наблюдение остановлено. История сохранена.':'Наблюдение возобновлено.');}catch(error){competitorState.formError=error.message;}finally{competitorState.saving=false;competitorsRender();}}
async function competitorQueue(id){if(competitorState.queueing)return;competitorCaptureDraft();competitorState.queueing=true;competitorsRender();try{await api('/api/competitors/queue',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(id?{target_id:id}:{})});await competitorsLoad();toast('Добавлено в очередь. Проверка выполнится при следующем фоновом запуске.');}catch(error){toast(error.message);}finally{competitorState.queueing=false;competitorsRender();}}
function competitorHistoryObservation(target,row){const observation=row.observation||row.data||row;const stamp=row.checked_at||row.observed_at||row.created_at||row.at;return `<article class="competitor-history-snapshot"><time>${esc(competitorDate(stamp))}</time>${(observation.offers||[]).map(o=>competitorOffer(target,o,false)).join('')}${observation.text?'<details><summary>Текст страницы в этом снимке</summary><pre>'+esc(observation.text)+'</pre></details>':''}${observation.links?'<p class="competitor-muted">Ссылок на странице: '+num(observation.links.length)+'</p>':''}${(observation.warnings||[]).length?'<p class="competitor-warning">'+esc(competitorWarnings(observation.warnings))+'</p>':''}</article>`;}
async function competitorHistory(id){state.customer=null;openDrawer('МОНИТОРИНГ · ИСТОРИЯ');const sequence=++competitorState.historySequence;try{const history=await api('/api/competitors/targets/'+id);if(sequence!==competitorState.historySequence||!$('#drawer').open)return;const target=history.target;$('#drawer-content').innerHTML=`<div class="competitor-history"><span class="competitor-source-label">${esc(competitorSource(target.source_id).name)}</span><h2 class="drawer-name">${esc(target.label||target.observation?.title||'История страницы')}</h2><p>${competitorLink(target.url,'Открыть источник')}</p><p class="competitor-muted">Снимки и попытки проверки этой ссылки. Время — Киев.</p><h3>Успешные снимки</h3>${(history.observations||[]).map(row=>competitorHistoryObservation(target,row)).join('')||'<p class="competitor-muted">Успешных снимков пока нет.</p>'}<h3>Последние попытки</h3><div class="competitor-attempt-list">${(history.attempts||[]).map(a=>`<div><time>${esc(competitorDate(a.checked_at))}</time><span>${a.state==='ok'?'Успешно':esc(competitorErrors[a.error_code]||'Проверка не завершена')}${a.http_status?' · HTTP '+esc(a.http_status):''}</span></div>`).join('')||'<p class="competitor-muted">Попыток пока не было.</p>'}</div></div>`;}catch(error){if(sequence===competitorState.historySequence)$('#drawer-content').innerHTML='<div class="notice">'+esc(error.message)+'</div>';}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-comp-action]');if(!button)return;const action=button.dataset.compAction,id=Number(button.dataset.id);if(action==='refresh')competitorsLoad();if(action==='show-errors')competitorShowErrors();if(action==='tab'){competitorCaptureDraft();competitorState.tab=button.dataset.tab;if(competitorState.tab==='errors'){competitorState.source='all';competitorState.search='';competitorState.archived=false;}competitorsRender();document.getElementById('competitor-tab-'+competitorState.tab)?.focus();}if(action==='add')competitorOpenForm({kind:button.dataset.kind||'product',...(button.dataset.source?{source_id:button.dataset.source}:{})});if(action==='track-discovery')competitorOpenForm({kind:'product',source_id:button.dataset.source,url:button.dataset.url,label:button.dataset.title});if(action==='edit'){const target=competitorState.data.targets.find(t=>t.id===id);if(target)competitorOpenForm(target);}if(action==='cancel-form'&&!competitorState.saving){competitorState.formOpen=false;competitorState.draft=null;competitorState.formError='';competitorsRender();}if(action==='archive')competitorArchive(id);if(action==='queue')competitorQueue(id);if(action==='history')competitorHistory(id);});
document.addEventListener('submit',event=>{if(event.target.id==='competitor-target-form'){event.preventDefault();competitorSave();}});
document.addEventListener('input',event=>{if(event.target.closest('#competitor-target-form'))competitorCaptureDraft();if(event.target.id==='competitor-search'){competitorState.search=event.target.value;const pos=event.target.selectionStart;competitorCaptureDraft();competitorsRender();const input=document.getElementById('competitor-search');input?.focus();input?.setSelectionRange(pos,pos);}});
document.addEventListener('change',event=>{if(event.target.closest('#competitor-target-form')){competitorCaptureDraft();if(event.target.name==='kind')competitorsRender();}if(event.target.id==='competitor-source'){competitorCaptureDraft();competitorState.source=event.target.value;competitorsRender();}if(event.target.id==='competitor-archived'){competitorCaptureDraft();competitorState.archived=event.target.checked;competitorsRender();}});
document.addEventListener('keydown',event=>{const button=event.target.closest('.competitor-tabs [role=tab]');if(!button||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...button.parentElement.children],current=tabs.indexOf(button),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(current+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();});

// Matrix actions calculate an in-memory draft only; the only optional write here
// confirms an existing comparison link, through the existing target settings API.
document.addEventListener('click',event=>{const button=event.target.closest('[data-comp-action]');if(!button)return;const action=button.dataset.compAction;if(action==='matrix-detail')competitorMatrixDetail(button.dataset.row,button.dataset.source);if(action==='matrix-confirm')competitorMatrixConfirm(Number(button.dataset.id));if(action==='matrix-add'){const row=competitorMatrixRows().find(item=>item.key===button.dataset.row);if(row)competitorOpenForm({kind:'product',source_id:button.dataset.source,match_group:row.group,label:row.label,match_confirmed:false});}if(action==='matrix-select-ready'){competitorVisibleRows().filter(row=>row.comparable).forEach(row=>competitorState.selected[row.key]=true);competitorState.preview=false;competitorsRender();}if(action==='matrix-preview'){competitorState.preview=true;competitorsRender();toast('Черновик рассчитан. Цены магазина не изменены.');}if(action==='matrix-clear'){competitorState.selected={};competitorState.preview=false;competitorsRender();}if(action==='matrix-show-above'){competitorState.tab='products';competitorState.matrixStatus='above';competitorsRender();document.getElementById('competitor-tabpanel')?.scrollIntoView({block:'start'});}if(action==='copy-errors')competitorCopyErrors();});
document.addEventListener('change',event=>{if(event.target.id==='competitor-matrix-pack'){competitorState.matrixPack=event.target.value;competitorsRender();}if(event.target.id==='competitor-matrix-status'){competitorState.matrixStatus=event.target.value;competitorsRender();}if(event.target.id==='competitor-matrix-sort'){competitorState.matrixSort=event.target.value;competitorsRender();}if(event.target.dataset.matrixSelect){competitorState.selected[event.target.dataset.matrixSelect]=event.target.checked;competitorState.preview=false;competitorsRender();}});
document.addEventListener('input',event=>{if(event.target.id==='competitor-batch-cut'){competitorState.cut=event.target.value;competitorState.preview=false;document.querySelectorAll('[data-matrix-cut]').forEach(input=>{if(!Object.prototype.hasOwnProperty.call(competitorState.cuts,input.dataset.matrixCut))input.value=competitorState.cut;});document.querySelectorAll('.competitor-suggestion').forEach(node=>node.remove());}if(event.target.dataset.matrixCut){competitorState.cuts[event.target.dataset.matrixCut]=event.target.value;competitorState.preview=false;document.querySelectorAll('.competitor-suggestion').forEach(node=>node.remove());}});
async function competitorCopyErrors(){const rows=competitorFailedTargets(),text=rows.map(target=>[competitorSource(target.source_id).name,target.label||'Страница',target.url,'Ошибка: '+(target.last_attempt.error_code||'unknown')+(target.last_attempt.http_status?' · HTTP '+target.last_attempt.http_status:''),'Попытка: '+competitorDate(target.last_attempt.checked_at),'Последний успех: '+competitorDate(target.last_success)].join('\n')).join('\n\n')||'Ошибок проверок нет.';try{if(!navigator.clipboard?.writeText)throw Error('clipboard_unavailable');await navigator.clipboard.writeText(text);toast('Список ошибок скопирован. Его можно прислать в чат.');}catch(_){state.customer=null;openDrawer('ПРОВЕРКИ · СПИСОК');$('#drawer-content').innerHTML='<div class="competitor-history"><h2 class="drawer-name">Список ошибок</h2><p class="competitor-muted">Выделите и скопируйте текст. Здесь только наблюдаемые публичные страницы и результаты проверок.</p><textarea id="competitor-errors-copy" class="competitor-errors-copy" readonly aria-label="Список ошибок для копирования">'+esc(text)+'</textarea></div>';const field=document.getElementById('competitor-errors-copy');field?.focus();field?.select();}}
